/* src/data/math_problems.js */
function buildProblems(){
  const problems = [];
  for(let a = 0; a <= 10; a++){
    for(let b = 0; b <= 10; b++){
      const sum = a + b;
      if(sum <= 10){
        problems.push({
          a,
          b,
          answer: sum,
          label: `${a} + ${b}`,
          key: `${a}+${b}`
        });
      }
    }
  }
  return problems;
}

const MATH_PROBLEMS = buildProblems();


/* src/core/storage.js */
const KEYS = { STARS:'ll_stars', STICKERS:'ll_stickers', COOLDOWN:'ll_cooldown_until' };

function load() {
  let stars = 0, stickers = [], cooldownUntil = 0;
  try {
    stars = parseInt(localStorage.getItem(KEYS.STARS) || '0', 10);
    stickers = JSON.parse(localStorage.getItem(KEYS.STICKERS) || '[]');
    cooldownUntil = parseInt(localStorage.getItem(KEYS.COOLDOWN) || '0', 10);
  } catch {}
  return { stars: Number.isFinite(stars) ? stars : 0, stickers: Array.isArray(stickers) ? stickers : [], cooldownUntil };
}
function saveStars(v){ try{ localStorage.setItem(KEYS.STARS, String(v)); }catch{} }
function saveStickers(arr){ try{ localStorage.setItem(KEYS.STICKERS, JSON.stringify(arr)); }catch{} }
function setCooldownUntil(ts){ try{ localStorage.setItem(KEYS.COOLDOWN, String(ts)); }catch{} }
function getCooldownUntil(){ return parseInt(localStorage.getItem(KEYS.COOLDOWN)||'0',10); }


/* src/core/state.js */
const listeners = new Set();
const initial = load();

const state = {
  stars: initial.stars,
  stickers: initial.stickers,
  streak: 0,
  firstTry: true,
  audioOn: true,
  recentWords: [], // laatste juiste woorden (voor no‑repeat)
};

/* ---------- Pub/Sub ---------- */
function subscribe(fn){ listeners.add(fn); return ()=>listeners.delete(fn); }
function emit(){ listeners.forEach(fn => fn(state)); }

/* ---------- Setters (en persistentie) ---------- */
function setStars(v){ state.stars = v; saveStars(v); emit(); }
function addSticker(s){
  if(!state.stickers.includes(s)){
    state.stickers.push(s);
    saveStickers(state.stickers);
    emit();
  }
}
function setStreak(v){ state.streak = v; emit(); }
function setFirstTry(v){ state.firstTry = v; emit(); }
function toggleAudio(){ state.audioOn = !state.audioOn; emit(); }

/* ---------- Recent / no‑repeat venster ---------- */
function pushRecent(word, windowSize){
  state.recentWords.push(word);
  if(state.recentWords.length > windowSize) state.recentWords.shift();
  emit();
}

/* ---------- Resets ---------- */
function clearStickers(){
  state.stickers = [];
  saveStickers([]);
  emit();
}

/** Volledige sessie resetten (scores, streak, recent; optioneel ook stickers) */
function resetSession({ resetStickers = false } = {}){
  state.stars = 0; saveStars(0);
  state.streak = 0;
  state.firstTry = true;
  state.recentWords = [];
  if(resetStickers){
    state.stickers = [];
    saveStickers([]);
  }
  emit();
}


/* src/core/sampler.js */
function pick(list, recent, key){
  const get = x => key ? x[key] : x;
  let candidates = list.filter(x => !recent.includes(get(x)));
  if(candidates.length === 0){ recent.length = 0; candidates = list.slice(); }
  return candidates[Math.floor(Math.random()*candidates.length)];
}


/* src/core/rewards.js */
function nextThreshold(stars = state.stars){
  for(const t of REWARD_TIERS) if(stars < t.threshold) return t;
  return null;
}

function checkAndAward(onSticker){
  const tier = REWARD_TIERS.find(t => t.threshold === state.stars);
  if(tier && !state.stickers.includes(tier.sticker)){
    addSticker(tier.sticker);
    onSticker && onSticker(tier.sticker);
  }
}

function incrementStarsWithAntiGuess(streakBonusEvery = 5){
  let newStreak = state.streak;
  if(state.firstTry){
    setStars(state.stars + 1);
    newStreak = state.streak + 1;
    if(newStreak % streakBonusEvery === 0){
      setStars(state.stars + 1);
    }
  } else {
    newStreak = 0;
  }
  return newStreak;
}


/* src/core/timer.js */
let sessionStart = 0, ticker = null;

function isPaused(){ return Date.now() < getCooldownUntil(); }

function ensureStartAllowed(showOverlay){
  const until = getCooldownUntil();
  if(Date.now() < until){ showOverlay(until); return false; }
  sessionStart = Date.now();
  if(ticker) clearInterval(ticker);
  ticker = setInterval(()=>{
    if(Date.now() - sessionStart >= SESSION_LIMIT_MS){
      const newUntil = Date.now() + COOLDOWN_MS;
      setCooldownUntil(newUntil);
      showOverlay(newUntil);
      clearInterval(ticker);
    }
  }, 1000);
  return true;
}


/* src/core/tts.js */
function speak(text){
  try{
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'nl-NL'; u.rate = 0.9; u.pitch = 1.0;
    speechSynthesis.cancel(); speechSynthesis.speak(u);
  }catch{}
}


/* src/ui/confetti.js */
function fireConfetti(){
  const c = $('#confetti');
  const emojis = ['🎉','✨','⭐','🎊','💫'];
  for(let i=0;i<24;i++){
    const el = document.createElement('i');
    el.textContent = emojis[Math.floor(Math.random()*emojis.length)];
    el.style.left = Math.random()*100 + '%';
    el.style.transform = `translateY(0) rotate(${Math.random()*180}deg)`;
    c.appendChild(el);
    setTimeout(()=> el.remove(), 2300);
  }
}


/* src/ui/overlay.js */
function showPauseOverlay(untilTs){
  const overlay = $('#pause-overlay');
  const remainEl = $('#pause-remaining');
  overlay.classList.add('show');
  const tick = ()=>{
    const remain = Math.max(0, untilTs - Date.now());
    const s = Math.ceil(remain/1000), m = Math.floor(s/60), r = s%60;
    remainEl.textContent = `${String(m).padStart(2,'0')}:${String(r).padStart(2,'0')}`;
    if(remain <= 0){ overlay.classList.remove('show'); clearInterval(tid); }
  };
  tick();
  const tid = setInterval(tick, 1000);
}


/* src/ui/trophy.js */
function renderTrophyCase(stickers){
  const grid = $('#trophy-grid'); grid.innerHTML = '';
  REWARD_TIERS.forEach(t=>{
    const unlocked = stickers.includes(t.sticker);
    const item = el('div',{className:'trophy-item'+(unlocked?'':' locked')});
    item.dataset.label = t.sticker;
    item.append(el('span',{className:'trophy-emoji', textContent:t.sticker.split(' ')[0]}));
    item.append(el('span',{textContent:`${t.sticker} — ${t.threshold}⭐`}));
    grid.append(item);
  });
}
function flashSticker(sticker){
  const item = [...document.querySelectorAll('#trophy-grid .trophy-item')]
    .find(x=>x.dataset.label===sticker);
  if(item){ item.classList.add('flash'); setTimeout(()=>item.classList.remove('flash'), 1000); }
}
function setNextText(text){ $('#sticker-next').textContent = text; }
function animateStickerToTrophy(sticker){
  const float = $('#sticker-float');
  float.textContent = sticker.split(' ')[0];
  float.classList.add('show');
  setTimeout(()=> float.classList.remove('show'), 2000);
  setTimeout(()=> flashSticker(sticker), 900);
}


/* src/modes/emoji.js */
function mountEmoji(){
  const root = $('#screen-emoji'); 
  root.innerHTML = '';

  const toolbar = el('div',{className:'toolbar'},
    el('button',{className:'btn secondary', id:'emoji-back', textContent:'← Home'}),
    el('div',{className:'pill', textContent:'Kies het juiste woord'}),
    el('div',{className:'pill'}, '⭐ ', el('span',{id:'stars-emoji'})),
    el('div',{className:'pill'}, '🔗 ', el('span',{id:'streak-emoji'})),
    el('div',{className:'pill'}, '🎁 Nog ', el('span',{id:'countdown-emoji'}),' goed'),
    el('button',{className:'btn secondary', id:'emoji-reset', textContent:'🔄 Reset'})
  );

  const symbol  = el('div',{className:'big', id:'emoji-symbol', style:'text-align:center;margin:12px'},'❓');
  const options = el('div',{id:'emoji-options', className:'grid cols-2'});
  const feedback= el('div',{id:'emoji-feedback',className:'center muted',style:'margin-top:12px'});
  root.append(toolbar, symbol, options, feedback);

  $('#emoji-back').onclick = ()=> history.back();

  // 🔄 Reset: alles terug naar 0 + stickers leeg + nieuwe ronde
  $('#emoji-reset').onclick = ()=>{
    resetSession({ resetStickers:true });
    syncToolbar();
    nextRound();
  };

  function updateCountdown(){
    const nxt = nextThreshold(state.stars);
    $('#countdown-emoji').textContent = nxt ? (nxt.threshold - state.stars) : 0;
  }

  function syncToolbar(){
    const sEl = $('#stars-emoji');
    const tEl = $('#streak-emoji');
    if (sEl) sEl.textContent = state.stars;
    if (tEl) tEl.textContent = state.streak;
    updateCountdown();
  }

  // live meebewegen met state-veranderingen (stars/streak)
  const unsubscribe = subscribe(syncToolbar);

  const isEmojiChar = (s) => /^[\u2190-\u2BFF\u1F300-\u1F9FF]$/.test(s);

  let current = null;

  function nextRound(){
    setFirstTry(true);
    current = pick(EMOJI_WORDS, state.recentWords, 'word');
    $('#emoji-symbol').textContent = current.emoji;

    feedback.textContent = '';
    options.innerHTML = '';

    const opts = new Set([current.word]);
    while(opts.size < 4){
      const rnd = EMOJI_WORDS[Math.floor(Math.random()*EMOJI_WORDS.length)].word;
      if(!opts.has(rnd)) opts.add(rnd);
    }

    [...opts].sort(()=>Math.random()-0.5).forEach(w=>{
      const className = isEmojiChar(w) ? 'btn emoji-option' : 'btn word-option';
      const b = el('button',{ className, textContent:w });

      b.onclick = ()=>{
        if(!ensureStartAllowed(showPauseOverlay)) return;
        [...options.children].forEach(x=>x.disabled = true);

        if(w === current.word){
          b.classList.add('ok');
          feedback.textContent = state.firstTry ? 'Top! Eerste poging! ⭐' : 'Goed!';
          const newStreak = incrementStarsWithAntiGuess();
          setStreak(state.firstTry ? newStreak : 0);
          pushRecent(current.word, NO_REPEAT_WINDOW);
          checkAndAward(animateStickerToTrophy);
          fireConfetti();
          updateCountdown();
          setTimeout(nextRound, 900);
        } else {
          b.classList.add('err');
          feedback.textContent = 'Rustig kijken…';
          setFirstTry(false);
          setStreak(0);
          setTimeout(()=>{
            [...options.children].forEach(x=>{ if(x!==b) x.disabled=false; });
          }, 500);
        }
      };

      options.append(b);
    });

    syncToolbar();
  }

  nextRound();

  // optioneel: netjes unsubscriben als je een unmount-systeem toevoegt
  // return () => unsubscribe();
}


